'use client';

import { useEffect, useId } from 'react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ArrowUpRightIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Wash } from '@/registry/ndeko/ui/wash';

import {
  SERVICES,
  SITE,
  type AffectedService,
  type ServiceStatus,
} from './data';
import { MaintenanceClock } from './maintenance-clock';
import { NotifyForm } from './notify-form';
import {
  errorOf,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SAVE_MS,
  SCRIPT,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const STATUS_LABEL: Record<ServiceStatus, string> = {
  paused: 'Paused',
  readOnly: 'Read only',
  working: 'Working',
};

const STATUS_VARIANT: Record<ServiceStatus, 'warning' | 'info' | 'success'> = {
  paused: 'warning',
  readOnly: 'info',
  working: 'success',
};

const CARD =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

function ServiceRow({ service }: { service: AffectedService }) {
  return (
    <li className='flex items-center gap-3 rounded-lg px-3 py-2.5'>
      <div className='flex min-w-0 flex-1 flex-col'>
        <p className='text-[13px] font-medium'>{service.name}</p>
        <p className='text-muted-foreground text-xs text-pretty'>
          {service.note}
        </p>
      </div>
      <Badge variant={STATUS_VARIANT[service.status]}>
        {STATUS_LABEL[service.status]}
      </Badge>
    </li>
  );
}

export default function ErrorPages03() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const affectedId = useId();
  const isSaving = state.status === 'saving';
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;
  useKeptHeight(ref);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** The address is saved on its own once sent. A focus held by the form follows it to the message. */
  useEffect(() => {
    if (!isSaving) {
      return;
    }
    const timer = setTimeout(() => {
      const form = ref.current?.querySelector('form');
      const active = document.activeElement;
      const hadFocus = form?.contains(active) ?? false;
      act({ type: 'saved' });
      if (!hadFocus) {
        return;
      }
      requestAnimationFrame(() => {
        const done =
          ref.current?.querySelector<HTMLElement>('[data-notify-done]');
        done?.focus();
      });
    }, SAVE_MS);
    return () => clearTimeout(timer);
  }, [isSaving, act, ref]);

  /** A refused address sends the person back to the field, where the reason is read with it. */
  function submit() {
    const isRefused = errorOf(state.email) !== null;
    act({ type: 'submitted' });
    if (isRefused) {
      focusLater('[data-notify-field]');
    }
  }

  function edit() {
    act({ type: 'edited' });
    focusLater('[data-notify-field]');
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container flex min-h-dvh w-full flex-col'
      >
        <header className='flex min-h-16 items-center gap-3 px-4 @2xl:px-8'>
          <a
            href={SITE.homeHref}
            className={cn(
              'flex items-center gap-2 rounded-md text-sm font-semibold',
              FOCUS_RING
            )}
          >
            <CompanyMark seed={SITE.name} size='lg' />
            {SITE.name}
          </a>
          <span className='flex-1' />
          <ReplayButton isShown={canReplay} onReplay={restart} label='Replay' />
        </header>

        <main className='flex flex-1 flex-col items-center px-4 pt-4 pb-16 @2xl:pt-10'>
          <div className='flex w-full max-w-xl flex-col gap-6'>
            <div className='flex flex-col gap-3'>
              <p className='text-info-foreground flex items-center gap-2 text-xs font-medium'>
                <span
                  aria-hidden='true'
                  className={cn(
                    'bg-info size-2 animate-pulse rounded-full',
                    !isInView && '[animation-play-state:paused]!'
                  )}
                />
                Maintenance in progress
              </p>
              <h1 className='text-2xl font-semibold text-balance @sm:text-3xl'>
                We are moving Quayside to a faster database
              </h1>
              <p className='text-muted-foreground text-sm text-pretty'>
                Booking is paused while every clinic calendar is copied and
                checked. Nothing is lost, and reminders still go out on time.
              </p>
            </div>

            <section
              aria-label='Time left'
              className={cn(CARD, 'relative isolate p-5')}
            >
              <Wash color='var(--info)' />
              <MaintenanceClock />
            </section>

            <section
              aria-labelledby={affectedId}
              className='flex flex-col gap-2'
            >
              <div className='flex items-baseline justify-between gap-3 px-1'>
                <h2 id={affectedId} className='text-[13px] font-medium'>
                  What is affected
                </h2>
                <a
                  href={SITE.statusHref}
                  target='_blank'
                  rel='noreferrer'
                  className={cn(
                    'text-primary-ink inline-flex items-center gap-1 rounded-sm text-xs font-medium underline-offset-4 hover:underline',
                    FOCUS_RING
                  )}
                >
                  Status page
                  <ArrowUpRightIcon className='size-3.5' />
                </a>
              </div>
              <ul className={cn(CARD, 'flex flex-col p-1')}>
                {SERVICES.map((service) => (
                  <ServiceRow key={service.id} service={service} />
                ))}
              </ul>
            </section>

            <section aria-label='Notify me' className={cn(CARD, 'p-5')}>
              <NotifyForm
                state={state}
                pressed={pressed}
                onType={(value) => act({ type: 'typed', value })}
                onSubmit={submit}
                onEdit={edit}
              />
            </section>
          </div>
        </main>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { useNow } from '@/registry/ndeko/hooks/use-agent-run';

import { WINDOW } from './data';

const SECOND_MS = 1000;

const MINUTE_MS = 60_000;

const TWO_DIGITS = { minimumIntegerDigits: 2 };

const LOADED_AT = Date.now();

const STARTED_AT = LOADED_AT - WINDOW.startedBeforeLoadMs;

const ENDS_AT = STARTED_AT + WINDOW.plannedMs;

const LEFT_AT_LOAD = WINDOW.plannedMs - WINDOW.startedBeforeLoadMs;

const PLANNED_MINUTES = Math.round(WINDOW.plannedMs / MINUTE_MS);

type Left = {
  minutes: number;
  seconds: number;
};

function leftOf(remainingMs: number): Left {
  const totalSeconds = Math.ceil(remainingMs / SECOND_MS);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return { minutes, seconds };
}

function twoDigits(value: number) {
  const text = String(value);
  return text.padStart(2, '0');
}

function shareOf(now: number) {
  const elapsed = now - STARTED_AT;
  const share = elapsed / WINDOW.plannedMs;
  const atLeastNone = Math.max(0, share);
  return Math.min(1, atLeastNone);
}

function startedLineOf(now: number) {
  const elapsed = now - STARTED_AT;
  const minutes = Math.floor(elapsed / MINUTE_MS);
  if (minutes < 1) {
    return 'Started less than a minute ago';
  }
  if (minutes === 1) {
    return 'Started 1 minute ago';
  }
  return `Started ${minutes} minutes ago`;
}

function spokenLeftOf(left: Left) {
  if (left.minutes < 1) {
    return 'Less than a minute left';
  }
  if (left.minutes === 1) {
    return 'About 1 minute left';
  }
  return `About ${left.minutes} minutes left`;
}

/**
 * The only part of the page that ticks. Until the browser has a clock, the planned figure stands
 * in, so the page and its first paint agree; the clock takes over at the same value. The seconds
 * tick without stopping, so they are plain figures; the minutes change once a minute and roll.
 */
export function MaintenanceClock() {
  const now = useNow(SECOND_MS);
  const hasClock = now > 0;
  let remaining = LEFT_AT_LOAD;
  if (hasClock) {
    remaining = Math.max(0, ENDS_AT - now);
  }
  const left = leftOf(remaining);
  const isOver = remaining === 0;
  let share = 1 - LEFT_AT_LOAD / WINDOW.plannedMs;
  if (hasClock) {
    share = shareOf(now);
  }
  const startedLine = startedLineOf(now);
  const barStyle = { transform: `scaleX(${share})` };

  return (
    <div className='flex flex-col gap-4'>
      <div className='flex flex-col gap-1.5'>
        <p className='text-muted-foreground text-xs'>Back in about</p>
        {isOver && (
          <p className='text-[28px] leading-none font-semibold'>
            Any minute now
          </p>
        )}
        {!isOver && (
          <p className='text-[28px] leading-none font-semibold tabular-nums'>
            <span className='sr-only'>{spokenLeftOf(left)}</span>
            {!hasClock && (
              <span aria-hidden='true'>
                {twoDigits(left.minutes)}:{twoDigits(left.seconds)}
              </span>
            )}
            {hasClock && (
              <span aria-hidden='true' className='inline-flex items-baseline'>
                <MotionNumber value={left.minutes} format={TWO_DIGITS} />
                <span>:{twoDigits(left.seconds)}</span>
              </span>
            )}
          </p>
        )}
      </div>
      <div className='flex flex-col gap-2'>
        <div className='bg-foreground/10 h-1 overflow-hidden rounded-full'>
          <div
            style={barStyle}
            className='bg-info h-full origin-left rounded-full transition-transform duration-1000 ease-linear'
          />
        </div>
        <p className='text-muted-foreground flex flex-wrap justify-between gap-x-3 text-xs tabular-nums'>
          {hasClock && <span>{startedLine}</span>}
          {!hasClock && <span>Started a few minutes ago</span>}
          <span>Planned for {PLANNED_MINUTES} minutes</span>
        </p>
      </div>
    </div>
  );
}

'use client';

import { motion } from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { Input } from '@/registry/ndeko/ui/input';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';

import type { NotifyState, NotifyStatus } from './session';

const SUBMIT_STATE: Record<NotifyStatus, MorphState> = {
  idle: 'idle',
  saving: 'busy',
  confirmed: 'done',
};

const SUBMIT_LABELS: Record<MorphState, string> = {
  idle: 'Notify me',
  busy: 'Saving',
  done: 'Saved',
};

const NUDGE = { x: [0, -4, 4, -2, 0] };

const STILL = { x: 0 };

const NUDGE_TIMING = { duration: 0.32 };

function nudgeOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return STILL;
  }
  return NUDGE;
}

function describedByOf(hasError: boolean, hintId: string) {
  if (hasError) {
    return hintId;
  }
  return undefined;
}

type NotifyFormProps = {
  state: NotifyState;
  pressed: string | null;
  onType: (value: string) => void;
  onSubmit: () => void;
  onEdit: () => void;
};

export function NotifyForm({
  state,
  pressed,
  onType,
  onSubmit,
  onEdit,
}: NotifyFormProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const fieldId = useId();
  const hintId = useId();
  const isConfirmed = state.status === 'confirmed';
  const isSaving = state.status === 'saving';
  const hasError = state.error !== null;

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit();
  }

  return (
    <AnimatedSize>
      {!isConfirmed && (
        <form noValidate onSubmit={submit} className='flex flex-col gap-2.5'>
          <label htmlFor={fieldId} className='text-[13px] font-medium'>
            Email me when booking opens again
          </label>
          <div className='flex flex-col gap-2 @sm:flex-row'>
            <Input
              id={fieldId}
              data-notify-field
              type='email'
              inputMode='email'
              autoComplete='email'
              spellCheck={false}
              placeholder='you@clinic.com'
              value={state.email}
              readOnly={isSaving}
              aria-invalid={hasError}
              aria-describedby={describedByOf(hasError, hintId)}
              onChange={(event) => onType(event.target.value)}
              size='lg'
              className='@sm:flex-1'
            />
            <MorphButton
              type='submit'
              size='lg'
              state={SUBMIT_STATE[state.status]}
              labels={SUBMIT_LABELS}
              className={pressedSolidOf(pressed === 'notify')}
            />
          </div>
          {hasError && (
            <motion.p
              key={state.refusals}
              id={hintId}
              initial={STILL}
              animate={nudgeOf(shouldReduceMotion)}
              transition={NUDGE_TIMING}
              className='text-destructive-ink text-xs'
            >
              {state.error}
            </motion.p>
          )}
          {!hasError && (
            <p className='text-muted-foreground text-xs'>
              One email, then the address is deleted.
            </p>
          )}
        </form>
      )}
      {isConfirmed && (
        <div className='flex items-start gap-2.5 transition-opacity duration-200 starting:opacity-0'>
          <DrawnCheck
            tone='success'
            entrance='draw'
            pace='calm'
            className='mt-px'
          />
          <div className='flex min-w-0 flex-col items-start gap-1'>
            <p
              data-notify-done
              tabIndex={-1}
              className={cn('rounded-sm text-sm font-medium', FOCUS_RING)}
            >
              You are on the list
            </p>
            <p className='text-muted-foreground text-[13px] text-pretty'>
              We will email{' '}
              <span className='text-foreground font-medium break-all'>
                {state.email.trim()}
              </span>{' '}
              once, when booking opens again.
            </p>
            <button
              type='button'
              onClick={onEdit}
              className={cn(
                'text-primary-ink mt-1 rounded-sm text-xs font-medium underline-offset-4 hover:underline',
                FOCUS_RING
              )}
            >
              Use another address
            </button>
          </div>
        </div>
      )}
    </AnimatedSize>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

export type NotifyStatus = 'idle' | 'saving' | 'confirmed';

export type NotifyState = {
  email: string;
  status: NotifyStatus;
  /** Why the address was refused, shown under the field until it is edited. */
  error: string | null;
  /** Counts the refusals, so the same reason refused twice nudges twice. */
  refusals: number;
  spoken: string;
};

export type NotifyAction =
  | { type: 'typed'; value: string }
  | { type: 'submitted' }
  | { type: 'saved' }
  | { type: 'edited' };

type Step = SessionStep<NotifyState, NotifyAction>;

export const SAVE_MS = 1200;

const ENDING = /\.[^\s.@]{2,}$/;

export const INITIAL: NotifyState = {
  email: '',
  status: 'idle',
  error: null,
  refusals: 0,
  spoken: '',
};

export function errorOf(email: string) {
  const address = email.trim();
  if (address === '') {
    return 'Enter the address we should write to';
  }
  const parts = address.split('@');
  const [name, domain] = parts;
  const hasOneAt = parts.length === 2;
  const hasName = name !== '';
  const hasDomain = domain !== undefined && domain !== '';
  const isShaped = hasOneAt && hasName && hasDomain;
  if (!isShaped) {
    return 'An address has a name, an @ and a domain, like maya@clinic.com';
  }
  if (!ENDING.test(domain)) {
    return 'Add the ending of the address, such as .com';
  }
  return null;
}

function submitted(state: NotifyState): NotifyState {
  if (state.status !== 'idle') {
    return state;
  }
  const error = errorOf(state.email);
  if (error !== null) {
    return {
      ...state,
      error,
      refusals: state.refusals + 1,
      spoken: error,
    };
  }
  return { ...state, status: 'saving', spoken: 'Saving your address' };
}

function saved(state: NotifyState): NotifyState {
  if (state.status !== 'saving') {
    return state;
  }
  const address = state.email.trim();
  return {
    ...state,
    status: 'confirmed',
    spoken: `We will email ${address} when booking opens again`,
  };
}

export function reducer(state: NotifyState, action: NotifyAction): NotifyState {
  switch (action.type) {
    case 'typed':
      return { ...state, email: action.value, error: null };
    case 'submitted':
      return submitted(state);
    case 'saved':
      return saved(state);
    case 'edited':
      return { ...state, status: 'idle', spoken: '' };
  }
}

const KEY_MS = 65;

const FIRST_TRY = 'maya@harbourphysio';

const FIXED = `${FIRST_TRY}.com`;

function typing(text: string, from: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value: `${from}${value}` },
  }));
}

/**
 * A person leaves out the ending of the address and is told so, adds it, and is put on the list.
 * The address is saved on its own once it is sent.
 */
export const SCRIPT: Step[] = [
  ...typing(FIRST_TRY, '', 1600),
  { after: 650, by: 'demo', press: 'notify', action: { type: 'submitted' } },
  ...typing('.com', FIRST_TRY, 1500),
  { after: 600, by: 'demo', press: 'notify', action: { type: 'submitted' } },
];

/** Under reduced motion the address is on the list, with the way back to the form. */
export const RESTING: NotifyState = {
  email: FIXED,
  status: 'confirmed',
  error: null,
  refusals: 1,
  spoken: '',
};

export const LOOP_AFTER_MS = SAVE_MS + 3600;

export type ServiceStatus = 'paused' | 'readOnly' | 'working';

export type AffectedService = {
  id: string;
  name: string;
  note: string;
  status: ServiceStatus;
};

export const SITE = {
  name: 'Quayside',
  homeHref: '#',
  statusHref: 'https://status.quayside.example',
};

const MINUTE_MS = 60_000;

export const WINDOW = {
  plannedMs: 45 * MINUTE_MS,
  startedBeforeLoadMs: 6 * MINUTE_MS + 48_000,
};

export const SERVICES: AffectedService[] = [
  {
    id: 'booking',
    name: 'Online booking',
    note: 'Patients see this page and can still call the clinic',
    status: 'paused',
  },
  {
    id: 'calendars',
    name: 'Clinic calendars',
    note: 'Open to read while every appointment is copied',
    status: 'readOnly',
  },
  {
    id: 'reminders',
    name: 'Appointment reminders',
    note: 'Texts and emails go out on time',
    status: 'working',
  },
  {
    id: 'payments',
    name: 'Card payments at the desk',
    note: 'Card readers work as usual',
    status: 'working',
  },
];
